1	// Custom drawer menu: Feed / Folders tabs on top (inline note + folder lists),
2	// Sync and Settings pinned at the bottom. Opened with the hamburger on the
3	// capture page or a swipe from the left edge.
4	
5	import type { DrawerContentComponentProps } from "@react-navigation/drawer";
6	import { useState } from "react";
7	import { FlatList, Pressable, StyleSheet, Text, View } from "react-native";
8	import { useSafeAreaInsets } from "react-native-safe-area-context";
9	
10	import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
11	
12	import { findFolder, folderNoteRows } from "../lib/feed";
13	import type { RootStackParamList } from "../navigation";
14	import { useNotesStore } from "../state/notes-store";
15	import { useTheme } from "../theme";
16	import { NoteListRow } from "../screens/feed-screen";
17	
18	type DrawerTab = "feed" | "folders";
19	
20	export const AppDrawerContent = ({ navigation }: DrawerContentComponentProps) => {
21	  const theme = useTheme();
22	  const insets = useSafeAreaInsets();
23	  const [tab, setTab] = useState<DrawerTab>("feed");
24	
25	  const tree = useNotesStore((s) => s.tree);
26	  const previews = useNotesStore((s) => s.previews);
27	
28	  const openScreen = <Screen extends keyof RootStackParamList>(
29	    screen: Screen,
30	    params?: RootStackParamList[Screen]
31	  ) => {
32	    navigation.navigate("Home", { screen, params } as never);
33	    navigation.closeDrawer();
34	  };
35	
36	  const feedRows = folderNoteRows(findFolder(tree, FEED_FOLDER_PATH), previews);
37	  const folders = findFolder(tree, "")?.children ?? [];
38	
39	  return (
40	    <View
41	      style={[
42	        styles.root,
43	        {
44	          backgroundColor: theme.colors.background,
45	          paddingTop: insets.top + 8,
46	          paddingBottom: insets.bottom + 8,
47	        },
48	      ]}
49	    >
50	      <View style={[styles.tabs, { backgroundColor: theme.colors.surface }]}>
51	        <TabButton label="Feed" active={tab === "feed"} onPress={() => setTab("feed")} />
52	        <TabButton
53	          label="Folders"
54	          active={tab === "folders"}
55	          onPress={() => setTab("folders")}
56	        />
57	      </View>
58	
59	      {tab === "feed" ? (
60	        <FlatList
61	          style={styles.list}
62	          data={feedRows}
63	          keyExtractor={(row) => row.path}
64	          renderItem={({ item }) => (
65	            <NoteListRow
66	              row={item}
67	              theme={theme}
68	              onPress={() =>
69	                openScreen("Editor", {
70	                  path: item.path,
71	                  title: item.preview.title || "Note",
72	                })
73	              }
74	            />
75	          )}
76	          ListEmptyComponent={
77	            <Text style={[styles.empty, { color: theme.colors.secondaryText }]}>
78	              No notes yet — close the menu and start typing.
79	            </Text>
80	          }
81	        />
82	      ) : (
83	        <FlatList
84	          style={styles.list}
85	          data={folders}
86	          keyExtractor={(folder) => folder.path}
87	          renderItem={({ item }) => (
88	            <Pressable
89	              onPress={() => openScreen("Folder", { path: item.path, title: item.name })}
90	              style={({ pressed }) => [
91	                styles.folderRow,
92	                { borderBottomColor: theme.colors.border, opacity: pressed ? 0.6 : 1 },
93	              ]}
94	            >
95	              <Text style={[styles.folderName, { color: theme.colors.text }]}>
96	                {item.name}
97	              </Text>
98	              <Text style={[styles.folderMeta, { color: theme.colors.secondaryText }]}>
99	                {item.notes.length > 0 ? `${item.notes.length}` : ""} ›
100	              </Text>
101	            </Pressable>
102	          )}
103	          ListEmptyComponent={
104	            <Text style={[styles.empty, { color: theme.colors.secondaryText }]}>
105	              No folders yet.
106	            </Text>
107	          }
108	        />
109	      )}
110	
111	      <View style={[styles.bottom, { borderTopColor: theme.colors.border }]}>
112	        <BottomItem label="Sync" onPress={() => openScreen("Sync")} />
113	        <BottomItem label="Settings" onPress={() => openScreen("Settings")} />
114	      </View>
115	    </View>
116	  );
117	};
118	
119	const TabButton = ({
120	  label,
121	  active,
122	  onPress,
123	}: {
124	  label: string;
125	  active: boolean;
126	  onPress: () => void;
127	}) => {
128	  const theme = useTheme();
129	  return (
130	    <Pressable
131	      onPress={onPress}
132	      style={({ pressed }) => [
133	        styles.tab,
134	        {
135	          backgroundColor: active ? theme.colors.background : "transparent",
136	          opacity: pressed ? 0.7 : 1,
137	        },
138	      ]}
139	    >
140	      <Text
141	        style={[
142	          styles.tabLabel,
143	          { color: active ? theme.colors.text : theme.colors.secondaryText },
144	        ]}
145	      >
146	        {label}
147	      </Text>
148	    </Pressable>
149	  );
150	};
151	
152	const BottomItem = ({ label, onPress }: { label: string; onPress: () => void }) => {
153	  const theme = useTheme();
154	  return (
155	    <Pressable
156	      onPress={onPress}
157	      style={({ pressed }) => [styles.bottomItem, { opacity: pressed ? 0.6 : 1 }]}
158	    >
159	      <Text style={[styles.bottomLabel, { color: theme.colors.text }]}>{label}</Text>
160	      <Text style={{ color: theme.colors.secondaryText }}>›</Text>
161	    </Pressable>
162	  );
163	};
164	
165	const styles = StyleSheet.create({
166	  root: { flex: 1 },
167	  tabs: {
168	    flexDirection: "row",
169	    marginHorizontal: 12,
170	    marginBottom: 8,
171	    borderRadius: 10,
172	    padding: 3,
173	    gap: 3,
174	  },
175	  tab: {
176	    flex: 1,
177	    borderRadius: 8,
178	    paddingVertical: 8,
179	    alignItems: "center",
180	  },
181	  tabLabel: { fontSize: 14, fontWeight: "600" },
182	  list: { flex: 1 },
183	  empty: { textAlign: "center", marginTop: 32, fontSize: 13, paddingHorizontal: 16 },
184	  folderRow: {
185	    flexDirection: "row",
186	    alignItems: "center",
187	    justifyContent: "space-between",
188	    paddingHorizontal: 16,
189	    paddingVertical: 13,
190	    borderBottomWidth: StyleSheet.hairlineWidth,
191	  },
192	  folderName: { fontSize: 15, fontWeight: "600" },
193	  folderMeta: { fontSize: 13 },
194	  bottom: {
195	    borderTopWidth: StyleSheet.hairlineWidth,
196	    paddingTop: 4,
197	  },
198	  bottomItem: {
199	    flexDirection: "row",
200	    alignItems: "center",
