300	  if (!error) {
301	    return null;
302	  }
303	  const lower = error.toLowerCase();
304	  if (lower.includes("local changes detected")) {
305	    return "Pull blocked. Push local changes first.";
306	  }
307	  if (lower.includes("merge commit")) {
308	    return "Diverged history. Resolve on desktop, then pull on mobile.";
309	  }
310	  if (lower.includes("merge conflicts")) {
311	    return "Merge conflict detected. Resolve on desktop, then sync again.";
312	  }
313	  if (lower.includes("non-fast-forward")) {
314	    return "Remote is newer. Pull first, then push again.";
315	  }
316	  if (lower.includes("credentials")) {
317	    return "Authentication failed. Verify username and token.";
318	  }
319	  if (lower.includes("not initialized")) {
320	    return "Repository is not connected yet.";
321	  }
322	  return "Sync failed. Verify settings and retry.";
