2	import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
3	import { Pressable, RefreshControl, ScrollView, StyleSheet, Text } from "react-native";
4	
5	import { findFolder, folderNoteRows } from "../lib/feed";
6	import type { RootStackParamList } from "../navigation";
7	import { useNotesStore } from "../state/notes-store";
8	import { useTheme } from "../theme";
9	import { NoteListRow } from "./feed-screen";
10	
11	export const FolderScreen = () => {
12	  const theme = useTheme();
13	  const navigation =
14	    useNavigation<NativeStackNavigationProp<RootStackParamList>>();
15	  const route = useRoute<RouteProp<RootStackParamList, "Folder">>();
16	  const tree = useNotesStore((s) => s.tree);
17	  const previews = useNotesStore((s) => s.previews);
18	  const loading = useNotesStore((s) => s.loading);
19	  const refresh = useNotesStore((s) => s.refresh);
20	
21	  const folder = findFolder(tree, route.params.path);
22	  const rows = folderNoteRows(folder, previews);
23	
24	  return (
25	    <ScrollView
26	      style={{ backgroundColor: theme.colors.background }}
27	      refreshControl={
28	        <RefreshControl refreshing={loading} onRefresh={() => void refresh()} />
29	      }
30	    >
31	      {folder?.children.map((child) => (
32	        <Pressable
33	          key={child.path}
34	          onPress={() =>
35	            navigation.push("Folder", { path: child.path, title: child.name })
36	          }
37	          style={({ pressed }) => [
38	            styles.folderRow,
39	            { borderBottomColor: theme.colors.border, opacity: pressed ? 0.6 : 1 },
40	          ]}
41	        >
42	          <Text style={[styles.folderName, { color: theme.colors.text }]}>
43	            {child.name}
44	          </Text>
45	          <Text style={[styles.folderMeta, { color: theme.colors.secondaryText }]}>
46	            {child.notes.length > 0 ? `${child.notes.length} notes` : ""} ›
47	          </Text>
48	        </Pressable>
49	      ))}
50	      {rows.map((row) => (
51	        <NoteListRow
