                {section.title}
              </Text>
            </View>
          )}
          renderItem={({ item }) => (
            <NoteListRow
              row={item}
              theme={theme}
              onPress={() =>
                openScreen("Editor", {
                  path: item.path,
                  title: item.preview.title || "Note",
                })
