            >
              <Text style={[styles.folderName, { color: theme.colors.text }]}>
                {item.name}
              </Text>
              <Text style={[styles.folderMeta, { color: theme.colors.secondaryText }]}>
                {item.notes.length > 0 ? `${item.notes.length}` : ""} ›
