1	import { Ionicons } from "@expo/vector-icons";
2	import {
3	  DarkTheme,
4	  DefaultTheme,
5	  DrawerActions,
6	  NavigationContainer,
7	} from "@react-navigation/native";
8	import { StatusBar } from "expo-status-bar";
9	import { useEffect, useRef, useState } from "react";
10	import { AppState, Linking, Pressable, StyleSheet, Text, View } from "react-native";
11	import { GestureHandlerRootView } from "react-native-gesture-handler";
12	import { SafeAreaProvider } from "react-native-safe-area-context";
13	
14	import { getErrorMessage } from "@typenotes/shared/errors";
15	import { parseSyncDeepLink } from "@typenotes/shared/sync-link";
16	
17	import { bootCore } from "./core/boot";
18	import { Drawer, navigateToScreen, navigationRef, Stack } from "./navigation";
19	import { CaptureScreen } from "./screens/capture-screen";
20	import { EditorScreen } from "./screens/editor-screen";
21	import { FeedScreen } from "./screens/feed-screen";
22	import { FolderScreen } from "./screens/folder-screen";
23	import { LockScreen } from "./screens/lock-screen";
24	import { RecordScreen } from "./screens/record-screen";
25	import {
26	  SettingsScreen,
27	  SettingsTranscriptionScreen,
28	  SettingsWorkingFoldersScreen,
29	} from "./screens/settings-screen";
30	import { SyncScreen } from "./screens/sync-screen";
31	import { useNotesStore } from "./state/notes-store";
32	import { isLocked, useSecurityStore } from "./state/security-store";
33	import { useSettingsStore } from "./state/settings-store";
34	import { useSyncStore } from "./state/sync-store";
35	import { useTheme } from "./theme";
36	import { AppDrawerContent } from "./ui/drawer-content";
37	
38	type BootPhase = { state: "booting" } | { state: "ready" } | { state: "failed"; error: string };
39	
40	// Settings/Sync are dead-end destinations reached only from the drawer (no
41	// real stack parent to pop back to), so their back button reopens the
42	// drawer instead of popping to Capture, and the native swipe-back gesture is
43	// disabled so an edge swipe there always reopens the drawer too — see the
44	// nav feedback in the "swipe from left edge" gotcha this fixes.
45	const MenuBackButton = ({ onPress }: { onPress: () => void }) => {
46	  const theme = useTheme();
47	  return (
48	    <Pressable
49	      onPress={onPress}
50	      hitSlop={10}
51	      style={({ pressed }) => [styles.menuButton, { opacity: pressed ? 0.6 : 1 }]}
52	    >
53	      <Ionicons name="chevron-back" size={22} color={theme.colors.accent} />
54	      <Text style={[styles.menuButtonText, { color: theme.colors.accent }]}>Menu</Text>
55	    </Pressable>
56	  );
57	};
58	
59	const HomeStack = () => {
60	  const theme = useTheme();
61	  return (
62	    <Stack.Navigator
63	      initialRouteName="Capture"
64	      screenOptions={{
65	        headerStyle: { backgroundColor: theme.colors.background },
66	        headerTintColor: theme.colors.text,
67	        headerShadowVisible: false,
68	        contentStyle: { backgroundColor: theme.colors.background },
69	      }}
70	    >
71	      <Stack.Screen
72	        name="Capture"
73	        component={CaptureScreen}
74	        options={{ headerShown: false }}
75	      />
76	      <Stack.Screen name="Feed" component={FeedScreen} />
77	      <Stack.Screen
78	        name="Folder"
79	        component={FolderScreen}
80	        options={({ route }) => ({ title: route.params.title })}
81	      />
82	      <Stack.Screen
83	        name="Editor"
84	        component={EditorScreen}
85	        options={({ route }) => ({ title: route.params.title ?? "Note" })}
86	      />
87	      <Stack.Screen name="Record" component={RecordScreen} />
88	      <Stack.Screen
89	        name="Sync"
90	        component={SyncScreen}
91	        options={({ navigation }) => ({
92	          gestureEnabled: false,
93	          headerLeft: () => (
94	            <MenuBackButton onPress={() => navigation.dispatch(DrawerActions.openDrawer())} />
95	          ),
96	        })}
97	      />
98	      <Stack.Screen
99	        name="Settings"
100	        component={SettingsScreen}
101	        options={({ navigation }) => ({
102	          gestureEnabled: false,
103	          headerLeft: () => (
104	            <MenuBackButton onPress={() => navigation.dispatch(DrawerActions.openDrawer())} />
105	          ),
106	        })}
107	      />
108	      <Stack.Screen
109	        name="SettingsWorkingFolders"
110	        component={SettingsWorkingFoldersScreen}
111	        options={{ title: "Working Folders" }}
112	      />
113	      <Stack.Screen
114	        name="SettingsTranscription"
115	        component={SettingsTranscriptionScreen}
116	        options={{ title: "Transcription" }}
117	      />
118	    </Stack.Navigator>
119	  );
120	};
121	
122	/**
123	 * A `type2://sync?...` link (from the desktop's QR code, scanned with the
124	 * system camera) drops the remote into the sync store and jumps to the Sync
125	 * screen, which applies it.
126	 */
127	const handleSyncUrl = (url: string | null) => {
128	  const params = url ? parseSyncDeepLink(url) : null;
129	  if (!params) {
130	    return;
131	  }
132	  useSyncStore.getState().setPendingLink(params);
133	  navigateToScreen("Sync");
134	};
135	
136	export default function App() {
137	  const theme = useTheme();
138	  const [phase, setPhase] = useState<BootPhase>({ state: "booting" });
139	  const demoMode = useSettingsStore((s) => s.demoMode);
140	  const initialUrlHandled = useRef(false);
141	
142	  useEffect(() => {
143	    let cancelled = false;
144	    (async () => {
145	      try {
146	        const { demoMode: demo } = await bootCore();
147	        useSettingsStore.getState().setDemoMode(demo);
148	        await useSecurityStore.getState().load();
149	        // While encrypted + locked, content calls are rejected by the core —
150	        // the lock screen's unlock reloads these stores instead.
151	        if (!isLocked(useSecurityStore.getState().state)) {
152	          await useSettingsStore.getState().load();
153	          await useNotesStore.getState().refresh();
154	          // Best-effort — populates the drawer's "last synced" label without
155	          // forcing the user through the Sync screen first.
156	          void useSyncStore.getState().refresh().catch(() => {});
157	        }
158	        if (!cancelled) {
159	          setPhase({ state: "ready" });
160	        }
161	      } catch (error) {
162	        if (!cancelled) {
163	          setPhase({ state: "failed", error: getErrorMessage(error) });
164	        }
165	      }
166	    })();
167	    return () => {
168	      cancelled = true;
169	    };
170	  }, []);
171	
172	  // Deep links while the app is running; the initial (cold-start) URL is
173	  // picked up in the container's onReady below.
174	  useEffect(() => {
175	    const subscription = Linking.addEventListener("url", ({ url }) =>
176	      handleSyncUrl(url)
177	    );
178	    return () => subscription.remove();
179	  }, []);
180	
181	  // Auto-lock when the app goes to background (if enabled in security prefs).
182	  useEffect(() => {
183	    const subscription = AppState.addEventListener("change", (next) => {
184	      const security = useSecurityStore.getState();
185	      if (
186	        next === "background" &&
187	        security.state?.encryption_enabled &&
188	        security.state.auto_lock_on_background
189	      ) {
190	        void security.lock();
191	      }
192	    });
193	    return () => subscription.remove();
194	  }, []);
195	
196	  const securityState = useSecurityStore((s) => s.state);
197	  const locked = isLocked(securityState);
198	
199	  if (phase.state !== "ready") {
200	    return (
201	      <View style={[styles.boot, { backgroundColor: theme.colors.background }]}>
202	        {phase.state === "failed" ? (
203	          <Text style={[styles.bootError, { color: theme.colors.danger }]}>
204	            {phase.error}
205	          </Text>
206	        ) : null}
207	        <StatusBar style={theme.dark ? "light" : "dark"} />
208	      </View>
209	    );
210	  }
211	
212	  if (locked) {
213	    return (
214	      <SafeAreaProvider>
215	        <LockScreen />
216	        <StatusBar style={theme.dark ? "light" : "dark"} />
217	      </SafeAreaProvider>
218	    );
219	  }
220	
221	  return (
222	    <GestureHandlerRootView style={styles.root}>
223	      <SafeAreaProvider>
224	        <NavigationContainer
